1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote: base premiums", () => {
5	  it("empty item list → premium 5 G (only the processing fee)", () => {
6	    const result = runScenario({
7	      customer: { yearsWithMHPCO: 0 },
8	      steps: [{ op: "quote", items: [] }],
9	    });
10	
11	    expect(result).toEqual({ results: [{ premium: 5 }] });
12	  });
13	  it.todo("a sword → base premium 100 G (+10 G first insurance + 5 G fee = 115 G)");
14	  it.todo("an amulet → base premium 60 G (+6 G first insurance + 5 G fee = 71 G)");
15	  it.todo("a staff → base premium 80 G (+8 G first insurance + 5 G fee = 93 G)");
16	  it.todo("a potion → base premium 40 G (+4 G first insurance + 5 G fee = 49 G)");
17	  it.todo("a single rune → base premium 25 G (component)");
18	  it.todo("a single moonstone → base premium 25 G (component)");
19	});
20	
21	describe("MHPCO Claim Office — quote: building block of 3 alike components", () => {
22	  it.todo("2 runes → 50 G base premium");
23	  it.todo("3 runes → 60 G base premium (block applies)");
24	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
25	  it.todo("7 runes → 175 G base premium");
26	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
27	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
28	});
29	
30	describe("MHPCO Claim Office — quote: premium modifiers", () => {
31	  it.todo("cursed sword adds 50 G risk surcharge (50 % of the item's base premium)");
32	  it.todo("sword with enchantment 5 adds 30 G high-enchantment surcharge");
33	  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
34	  it.todo("cursed sword with enchantment 5 gets both surcharges");
35	  it.todo("customer with exactly 2 years with MHPCO gets the 20 % loyalty discount");
36	  it.todo("customer with 1 year with MHPCO gets no loyalty discount");
37	  it.todo("every item in a quote carries the 10 % first insurance surcharge");
38	  it.todo("the customer's second quote gets the 15 % follow-up contract discount");
39	  it.todo("a 5 G processing fee is added at the very end of every premium");
40	});
41	
42	describe("MHPCO Claim Office — quote: modifier scope on multi-item policies", () => {
43	  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only the cursed item's base) → 210 G before further modifiers and fee");
44	  it.todo("policy-wide modifiers (loyalty, follow-up) apply to the sum of all item base premiums");
45	});
46	
47	describe("MHPCO Claim Office — quote: rounding in the MHPCO's favor", () => {
48	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
49	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
50	});
51	
52	describe("MHPCO Claim Office — quote: integration examples", () => {
53	  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
54	  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
55	});
56	
57	describe("MHPCO Claim Office — claim: standard reimbursement", () => {
58	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
59	  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
60	  it.todo("a dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
61	});
62	
63	describe("MHPCO Claim Office — claim: special clauses", () => {
64	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
65	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
66	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
67	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
68	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
69	});
70	
71	describe("MHPCO Claim Office — claim: insurance sum and cap", () => {
72	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
73	  it.todo("a cursed sword → cap 2000 G (based on the unmodified insurance value)");
74	  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
75	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
76	  it.todo("sword (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G, remaining cap 600 G; second payout 600 G, remaining cap 0 G");
77	});
78	
79	describe("MHPCO Claim Office — claim: multiple items of the same type", () => {
80	  it.todo("two insured swords both damaged → each damage entry gets its own deductible");
81	  it.todo("more damage entries of a type than the policy insures → the claim is rejected");
82	});
83	
84	describe("MHPCO Claim Office — errors", () => {
85	  it.todo("a quote with an unknown item type (e.g. broomstick) → error, no results");
86	  it.todo("a claim damaging an item that is not part of the policy (amulet when only a sword is insured) → error");
87	  it.todo("a claim damaging an item with an unknown type → error");
88	  it.todo("a claim with a damage entry of amount -200 → error");
89	});
90	
91	describe("MHPCO Claim Office — CLI", () => {
92	  it.todo("reads a scenario from stdin and writes {results: [...]} to stdout in step order");
93	  it.todo("exits with a non-zero status and writes an error description to stderr on an invalid scenario");
94	});
